/**
 * DeepMindQ — Golden Contact Dataset for Enterprise Testing
 * Milestone 3 — Section 3.4: Golden Dataset Fixtures
 *
 * Provides 50 realistic contacts across various industries, seniority levels,
 * and engagement states. Used for E2E workflow tests, AI recommendation tests,
 * and signal intelligence validation.
 */

export interface GoldenContact {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string | null;
  title: string;
  department: string;
  seniority: 'C-Level' | 'VP' | 'Director' | 'Manager' | 'Individual Contributor';
  company: string;
  industry: string;
  country: string;
  state: string;
  linkedinUrl: string | null;
  engagementScore: number; // 0-100
  influenceScore: number; // 0-100 (CEO=100, VP=70, Director=50, Manager=35, IC=20)
  lastContactDate: string | null; // ISO date
  tags: string[];
  isDecisionMaker: boolean;
  notes: string | null;
}

