// Helper functions for test data access
export function getContactsBySeniority(seniority: GoldenContact['seniority']): GoldenContact[] {
  return GOLDEN_CONTACTS.filter(c => c.seniority === seniority);
}

export function getContactsByIndustry(industry: string): GoldenContact[] {
  return GOLDEN_CONTACTS.filter(c => c.industry === industry);
}

export function getHighEngagementContacts(threshold = 70): GoldenContact[] {
  return GOLDEN_CONTACTS.filter(c => c.engagementScore >= threshold);
}

export function getDecisionMakers(): GoldenContact[] {
  return GOLDEN_CONTACTS.filter(c => c.isDecisionMaker);
}

export function getContactById(id: string): GoldenContact | undefined {
  return GOLDEN_CONTACTS.find(c => c.id === id);
}

export function getContactsByCompany(company: string): GoldenContact[] {
  return GOLDEN_CONTACTS.filter(c => c.company === company);
}

export function getContactsByCountry(country: string): GoldenContact[] {
  return GOLDEN_CONTACTS.filter(c => c.country === country);
}
